import backtrader as bt


class DynamicExitStrategy(bt.Strategy):
    params = (
        ('fast_period', 20),
        ('slow_period', 50),
    )

    def __init__(self):
        self.fast_sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.fast_period
        )
        self.slow_sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.slow_period
        )
        self.crossover = bt.indicators.CrossOver(self.fast_sma, self.slow_sma)
        self.order = None

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None

    def sell_below10(self):
        self.order = self.close()

    def sell_abv10(self):
        self.order = self.close()

    def next(self):
        if self.order:
            return

        if self.position:
            profit_percentage = (
                (self.data.close[0] - self.position.price)
                / self.position.price
                * 100.0
            )

            if profit_percentage < 10.0:
                self.sell_below10()
            elif profit_percentage > 10.0:
                self.sell_abv10()
            return

        if self.crossover[0] > 0:
            commission = self.broker.getcommissioninfo(self.data).p.commission
            size = self.broker.getcash() / (
                self.data.close[0] * (1.0 + commission)
            )
            self.order = self.buy(size=size)
